import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Count recent behavior over last 10 rounds
    recent = history[-10:] if n >= 10 else history
    opp_c = sum(1 for a, b in recent if b == 'C')
    opp_d = len(recent) - opp_c

    # If opponent has been mostly cooperative, cooperate but occasionally test
    if n < 5:
        return 'C'

    # Strong trigger: defected a lot recently -> punish briefly, then forgive
    if opp_d >= 4:
        # Punish for a few rounds, then try to restore cooperation
        if len(history) >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
        if len(history) >= 4 and sum(1 for a, b in history[-4:] if b == 'D') >= 3:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Detect long cooperation and exploit mildly
    if opp_c == len(recent) and n >= 20:
        # Mostly cooperate, but defect rarely for extra gain
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Generally reciprocal: copy opponent's last move, with slight noise-resistant forgiveness
    if opp_last == 'C':
        if my_last == 'D' and rng.random() < 0.25:
            return 'C'
        return 'C'
    else:
        # Opponent defected: retaliate, but sometimes forgive to avoid endless feuds
        if rng.random() < 0.25:
            return 'C'
        return 'D'
